library(euaiact)
f <- "EUAIACT_2026_07_27"
duty <- ermittle_pflicht("P_AIA_060_007",list(test_unter_artikel_60=TRUE,schwerwiegender_vorfall_waehrend_realtest_festgestellt=TRUE),f)
stopifnot(duty$wert$erfuellung=="NICHT_GEPRUEFT",identical(duty$wert$erfuellungskriterien,list("AIA_060_007_FOLGEN")))
evidence <- pruefe_tatbestand(duty$wert$erfuellungskriterien[[1L]],list(realtest_vorfall_nach_artikel_73_gemeldet=FALSE),f)
stopifnot(identical(evidence$wert,FALSE))
duty <- ermittle_pflicht("P_AIA_062_001_A",list(kmu_status=TRUE,reallabor_auswahlkriterien_erfuellt=TRUE,reallabor_zulassungsbedingungen_erfuellt=TRUE,sitz_oder_zweigniederlassung_in_union=TRUE),f)
stopifnot(duty$wert$erfuellung=="NICHT_GEPRUEFT")
evidence <- pruefe_tatbestand(duty$wert$erfuellungskriterien[[1L]],list(reallabor_kmu_prioritaet_tatsaechlich_gewaehrt=TRUE,reallabor_andere_geeignete_kmu_nicht_ausgeschlossen=FALSE),f)
stopifnot(identical(evidence$wert,FALSE))
fields <- names(eingabevertrag("AIA_060A_005_TESTFOLGEN")$felder)
stopifnot("realtest_vor_inverkehrbringen_oder_inbetriebnahme" %in% fields,"realtest_beendigung_behoerde_mitgeteilt" %in% fields,!any(c("realtestplan_erstellt","realtest_und_plan_ausdruecklich_genehmigt","realtest_registrierungsweg","systemvorhersagen_empfehlungen_entscheidungen_wirksam_umkehrbar") %in% fields))
duty <- ermittle_pflicht("P_AIA_060A_002",list(mitgliedstaat_entscheidet_anhang_i_b_realtests_zuzulassen=TRUE),f)
stopifnot("AIA_060A_005_NORMINHALT" %in% unlist(duty$wert$erfuellungskriterien),duty$wert$erfuellung=="NICHT_GEPRUEFT")
cat("Three real-test obligation and scope compositions passed\n")
